"use client";

import { useEffect, useState } from "react";
import { PageWrap } from "../../../shared/components/PageWrap";
import { StatCard } from "../../../shared/components/StatCard";
import type { DashboardData } from "../../../shared/types/dashboard";
import { getDashboard } from "../api/dashboardApi";

export function DashboardPage() {
  const [data, setData] = useState<DashboardData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  async function loadDashboard() {
    setIsLoading(true);
    setError(null);
    try {
      setData(await getDashboard());
    } catch {
      setError(
        "O BFF não respondeu. Verifique se o servidor está rodando na porta 9000.",
      );
    } finally {
      setIsLoading(false);
    }
  }

  useEffect(() => {
    void loadDashboard();
  }, []);

  return (
    <>
      <PageWrap id="overview">
        <section className="welcome-row d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4">
          <div>
            <p className="eyebrow">SEU ESPAÇO DE FOCO</p>
            <h1>
              Bom dia, Alex <span aria-hidden="true"><i className="bi bi-stars" /></span>
            </h1>
            <p className="subtitle">
              Um passo de cada vez. Você está construindo um ótimo ritmo.
            </p>
          </div>
          <button className="btn btn-primary new-session">
            <i className="bi bi-plus-lg" aria-hidden="true" /> Nova sessão
          </button>
        </section>
        {isLoading && (
          <div className="alert alert-light border">
            Carregando seu ritmo...
          </div>
        )}
        {error && (
          <div className="alert alert-warning d-flex justify-content-between align-items-center">
            <span>{error}</span>
            <button
              className="btn btn-sm btn-outline-dark"
              onClick={() => void loadDashboard()}
            >
              Tentar novamente
            </button>
          </div>
        )}
        {data && (
          <>
            <section
              className="row g-3 mb-4"
              aria-label="Resumo de produtividade"
            >
              <div className="col-md-4">
                <StatCard
                  label="Tempo em foco"
                  value={`${data.stats.focusMinutes} min`}
                  helper="+12% vs. ontem"
                  tone="blue"
                  icon="bi-stopwatch-fill"
                />
              </div>
              <div className="col-md-4">
                <StatCard
                  label="Sessões concluídas"
                  value={String(data.stats.completedSessions)}
                  helper="Meta diária: 6 sessões"
                  tone="orange"
                  icon="bi-check-circle-fill"
                />
              </div>
              <div className="col-md-4">
                <StatCard
                  label="Ritmo semanal"
                  value={`${data.stats.weeklyChange}%`}
                  helper="Você está acima da média"
                  tone="green"
                  icon="bi-graph-up-arrow"
                />
              </div>
            </section>
            <section className="row g-4">
              <div className="col-lg-7" id="sessions">
                <div className="surface-card focus-card">
                  <div className="d-flex justify-content-between align-items-start">
                    <div>
                      <p className="eyebrow">SESSÃO ATUAL</p>
                      <h2>Deep work</h2>
                      <p className="muted">
                        Projeto pessoal · Próximo intervalo às 10:45
                      </p>
                    </div>
                    <span className="status-dot">Em foco</span>
                  </div>
                  <div className="timer-ring">
                    <div>
                      <strong>24:38</strong>
                      <small>restantes</small>
                    </div>
                  </div>
                  <div className="d-flex justify-content-center gap-2">
                    <button className="btn btn-dark px-4">Pausar</button>
                    <button className="btn btn-light border">Encerrar</button>
                  </div>
                </div>
              </div>
              <div className="col-lg-5" id="tasks">
                <div className="surface-card task-card">
                  <div className="d-flex justify-content-between align-items-center mb-4">
                    <div>
                      <p className="eyebrow">PARA HOJE</p>
                      <h2>Suas tarefas</h2>
                    </div>
                    <button className="link-button">Ver todas</button>
                  </div>
                  {data.tasks.map((task) => (
                    <div className="task-row" key={task.id}>
                      <span
                        className={`task-check ${task.completed ? "completed" : ""}`}
                      >
                        {task.completed ? (
                          <i className="bi bi-check-lg" aria-hidden="true" />
                        ) : null}
                      </span>
                      <div>
                        <strong className={task.completed ? "done" : ""}>
                          {task.title}
                        </strong>
                        <small>{task.category}</small>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </section>
          </>
        )}
      </PageWrap>
    </>
  );
}
